import{cloneFigure,speciationFigure,fossilFigure}from './hist-figures.js?v=20261023-physicscomplete01';
const make=(title,steps,render,note)=>({title,steps,duration:16,render,note});
export const histFilms={
'hist-adult-clone':make('Follow the adult nucleus',['Remove the unfertilised egg nucleus.','Insert the adult body-cell nucleus.','Stimulate division to form an embryo.','Transfer the ball of embryo cells into a host uterus.'],p=>cloneFigure({kind:'adult-clone',progress:p}),'Conceptual adult cloning, not a laboratory protocol. Nuclear DNA follows the adult donor; egg cytoplasm/mitochondria and host environment are distinct. It does not guarantee success or identical phenotype. Symbolic scale and compressed time.'),
'hist-plant-clone':make('Multiply a useful plant',['Select a useful or rare parent.','Take a small group of plant cells.','Grow cells in culture.','Develop genetically identical new plants.'],p=>cloneFigure({kind:'plant-clone',progress:p}),'Conceptual tissue culture. A cutting is a different plant-cloning method. Timing, cell counts and scale symbolic; no recipe, success-rate or environmental-identity claim.'),
'hist-embryo':make('Separate an early embryo',['Use an embryo before cells specialise.','Separate early cells into groups.','Transfer the resulting embryos into host mothers.','The embryos develop in their hosts.'],p=>cloneFigure({kind:'embryo',progress:p}),'Conceptual embryo splitting, not adult nucleus transfer. Shapes and counts symbolic; not a clinical protocol or guarantee. Host environment may affect phenotype.'),
'hist-speciation':make('From isolation to reproductive isolation',['One population has inherited variation.','A barrier reduces gene flow.','Inherited differences accumulate under different conditions.','If fertile interbreeding is no longer possible, the GCSE criterion is met.'],p=>speciationFigure({progress:p}),'A conditional geographical pathway. Dots summarise different generations, not the same individuals changing colour. Selection, mutation and inheritance can produce divergence; isolation alone is insufficient. Many generations compressed; some populations never speciate. Simplified species criterion has limits for asexual organisms.'),
'hist-fossil-process':make('Preserve evidence through mineral replacement',['Remains enter sediment.','Burial and decay occur.','Minerals replace material.','Rock retains evidence of past life.'],p=>fossilFigure({progress:p}),'One conceptual fossilisation pathway. Prevented decay and preserved activity traces are alternatives. No real geological dates or universal preservation guarantee. Replay resets the illustration only.')};
